-- LoftLife game-domain schema. Account identity is owned by the edge-auth migration.
CREATE TABLE IF NOT EXISTS ll_profiles (user_id TEXT PRIMARY KEY REFERENCES ll_accounts(id) ON DELETE CASCADE, display_name TEXT NOT NULL, avatar_json TEXT NOT NULL, bio TEXT NOT NULL DEFAULT '', updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ll_wallets (user_id TEXT PRIMARY KEY REFERENCES ll_accounts(id) ON DELETE CASCADE, yuanzi BIGINT NOT NULL DEFAULT 0 CHECK (yuanzi >= 0), tongbao BIGINT NOT NULL DEFAULT 0 CHECK (tongbao >= 0));
CREATE TABLE IF NOT EXISTS ll_ledger (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, currency TEXT NOT NULL CHECK (currency IN ('yuanzi','tongbao')), delta BIGINT NOT NULL, balance_after BIGINT NOT NULL, reason TEXT NOT NULL, ref TEXT, idempotency_key TEXT, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ll_ledger_user ON ll_ledger(user_id, created_at DESC);
CREATE UNIQUE INDEX IF NOT EXISTS ll_ledger_idem ON ll_ledger(idempotency_key) WHERE idempotency_key IS NOT NULL;
CREATE TABLE IF NOT EXISTS ll_inventory (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK (kind IN ('furniture','clothing')), catalog_id TEXT NOT NULL, qty BIGINT NOT NULL DEFAULT 1 CHECK (qty >= 0), acquired_at BIGINT NOT NULL, UNIQUE (user_id, kind, catalog_id));
CREATE TABLE IF NOT EXISTS ll_suites (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL UNIQUE REFERENCES ll_accounts(id) ON DELETE CASCADE, number TEXT NOT NULL, floor INTEGER NOT NULL, name TEXT NOT NULL, items_json TEXT NOT NULL DEFAULT '[]', surfaces_json TEXT NOT NULL DEFAULT '{}', mood TEXT NOT NULL DEFAULT 'morning', is_public BOOLEAN NOT NULL DEFAULT FALSE, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ll_worlds (id TEXT PRIMARY KEY, owner_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, name TEXT NOT NULL, kind TEXT NOT NULL DEFAULT 'hangout', description TEXT NOT NULL DEFAULT '', access TEXT NOT NULL DEFAULT 'private' CHECK (access IN ('public','private','invite','friends','collab')), published BOOLEAN NOT NULL DEFAULT FALSE, items_json TEXT NOT NULL DEFAULT '[]', surfaces_json TEXT NOT NULL DEFAULT '{}', mood TEXT NOT NULL DEFAULT 'morning', max_visitors INTEGER NOT NULL DEFAULT 30, created_at BIGINT NOT NULL, updated_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ll_worlds_owner ON ll_worlds(owner_id);
CREATE INDEX IF NOT EXISTS ll_worlds_public ON ll_worlds(published, access);
CREATE TABLE IF NOT EXISTS ll_world_collaborators (world_id TEXT NOT NULL REFERENCES ll_worlds(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, role TEXT NOT NULL DEFAULT 'editor' CHECK (role IN ('editor')), created_at BIGINT NOT NULL, PRIMARY KEY (world_id, user_id));
CREATE TABLE IF NOT EXISTS ll_world_invites (world_id TEXT NOT NULL REFERENCES ll_worlds(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, created_at BIGINT NOT NULL, PRIMARY KEY (world_id, user_id));
CREATE TABLE IF NOT EXISTS ll_friendships (a TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, b TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, status TEXT NOT NULL CHECK (status IN ('pending','accepted')), requested_by TEXT NOT NULL, created_at BIGINT NOT NULL, PRIMARY KEY (a, b), CHECK (a < b));
CREATE TABLE IF NOT EXISTS ll_blocks (user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, blocked_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, created_at BIGINT NOT NULL, PRIMARY KEY (user_id, blocked_id), CHECK (user_id <> blocked_id));
CREATE TABLE IF NOT EXISTS ll_chat_messages (id TEXT PRIMARY KEY, scope TEXT NOT NULL CHECK (scope IN ('city','world','dm','party')), scope_id TEXT NOT NULL, user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, body TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ll_chat_scope ON ll_chat_messages(scope, scope_id, created_at DESC);
CREATE TABLE IF NOT EXISTS ll_reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, target_user_id TEXT NOT NULL REFERENCES ll_accounts(id) ON DELETE CASCADE, reason TEXT NOT NULL, details TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'open' CHECK (status IN ('open','reviewed','actioned')), created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS ll_audit_log (id TEXT PRIMARY KEY, actor_id TEXT REFERENCES ll_accounts(id) ON DELETE SET NULL, action TEXT NOT NULL, detail TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ll_audit_created ON ll_audit_log(created_at DESC);
CREATE TABLE IF NOT EXISTS ll_schema_migrations (version TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now());
INSERT INTO ll_schema_migrations(version) VALUES ('0002_game_domain') ON CONFLICT (version) DO NOTHING;